CREATE OR REPLACE FUNCTION ECAMS.NOTICD
(QRYCD IN VARCHAR2,NOTIGBN IN VARCHAR2,TELNO2 IN VARCHAR2)
RETURN VARCHAR2
IS
  VNOTICD   CHAR(1);
BEGIN
    VNOTICD := 'X';

    SELECT DECODE(HOLIDAYCHECK,'OK',CM_HOLIDAY,CM_COMMON)
      INTO VNOTICD
      FROM CMM0018
     WHERE CM_QRYCD=QRYCD
       AND CM_NOTIGBN=NOTIGBN;

    IF VNOTICD IS NULL THEN
       VNOTICD := 'X';
    END IF;

    RETURN VNOTICD;

end;